package org.eclipse.rdf4j.sail.lmdb;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertTrue;

import java.io.File;
import java.nio.ByteBuffer;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.SplittableRandom;

import org.eclipse.rdf4j.sail.lmdb.TxnManager.Txn;
import org.eclipse.rdf4j.sail.lmdb.config.LmdbStoreConfig;
import org.eclipse.rdf4j.sail.lmdb.estimate.LmdbPageCardinalityEstimator.ExactCount;
import org.eclipse.rdf4j.sail.lmdb.estimate.LmdbPageCardinalityEstimator.ExactPrefixCursor;
import org.eclipse.rdf4j.sail.lmdb.estimate.LmdbPageCardinalityEstimator.PrefixRun;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;
import org.junit.jupiter.params.ParameterizedTest;
import org.junit.jupiter.params.provider.ValueSource;

class ChunkedExactIndexCounterTest {

	@TempDir
	File dir;

	private static final int PREDICATES = 6;

	@ParameterizedTest
	@ValueSource(booleans = { true, false })
	void countsMatchBruteForceForEveryPrefix(boolean explicit) throws Exception {
		try (TripleStore store = seededStore()) {
			TripleIndex index = index(store, "posc");
			try (Txn txn = store.getTxnManager().createReadTxn()) {
				List<byte[]> keys = keys(store, txn, index, explicit);
				// Physical chunks of the plane; for the inferred plane the row count is a (weaker) ceiling.
				long chunks = explicit ? store.explicitIndexChunkCounts().get("posc") : keys.size();
				ExactCount all = count(txn, index, explicit, null, null);
				assertEquals(keys.size(), all.entries());
				assertTrue(all.work().leafHeadersRead() <= chunks, "one footer read per chunk: " + all.work());
				// Predicate 0 and PREDICATES + 1 are absent: empty ranges before and after all data.
				for (long predicate = 0; predicate <= PREDICATES + 1; predicate++) {
					byte[] lower = LmdbExactPrefixRunCursor.encodePrefix(new long[] { predicate });
					byte[] upper = LmdbExactPrefixRunCursor.successor(lower);
					ExactCount count = count(txn, index, explicit, lower, upper);
					assertEquals(bruteForce(keys, lower, upper), count.entries(), "predicate " + predicate);
					// At most every chunk plus the predecessor of the lower bound.
					assertTrue(count.work().leafHeadersRead() <= chunks + 1,
							"one footer read per chunk: " + count.work());
				}
				for (int sample = 0; sample < 50; sample++) {
					byte[] key = keys.get(sample * keys.size() / 50);
					ByteBuffer encoded = ByteBuffer.wrap(key);
					long predicate = Varint.readUnsigned(encoded);
					long object = Varint.readUnsigned(encoded);
					byte[] lower = LmdbExactPrefixRunCursor.encodePrefix(new long[] { predicate, object });
					byte[] upper = LmdbExactPrefixRunCursor.successor(lower);
					assertEquals(bruteForce(keys, lower, upper), count(txn, index, explicit, lower, upper).entries());
				}
			}
		}
	}

	@ParameterizedTest
	@ValueSource(ints = { 1, 2 })
	void prefixRunsMatchBruteForceGroups(int prefixLength) throws Exception {
		try (TripleStore store = seededStore()) {
			TripleIndex index = index(store, "posc");
			try (Txn txn = store.getTxnManager().createReadTxn()) {
				List<byte[]> keys = keys(store, txn, index, true);
				byte[] lower = prefixLength == 1 ? null : LmdbExactPrefixRunCursor.encodePrefix(new long[] { 3 });
				byte[] upper = lower == null ? null : LmdbExactPrefixRunCursor.successor(lower);
				Map<String, Long> expected = new LinkedHashMap<>();
				for (byte[] key : keys) {
					if (inRange(key, lower, upper)) {
						expected.merge(prefix(key, prefixLength), 1L, Long::sum);
					}
				}
				Map<String, Long> actual = new LinkedHashMap<>();
				try (ExactPrefixCursor runs = ChunkedExactIndexCounter.prefixRuns(txn.get(), index, true, lower,
						upper, prefixLength, () -> false)) {
					PrefixRun run;
					while ((run = runs.next()) != null) {
						String group = prefix(run.representativeKey(), prefixLength);
						assertEquals(null, actual.put(group, run.entries()), "every group is emitted once");
					}
					assertEquals(expected.size(), runs.work().keyPrefixesRead());
				}
				assertEquals(expected, actual);
				assertEquals(new ArrayList<>(expected.keySet()), new ArrayList<>(actual.keySet()),
						"groups are emitted in key order");
			}
		}
	}

	@Test
	void emptyIndexHasNoRowsAndNoGroups() throws Exception {
		try (TripleStore store = new TripleStore(dir, new LmdbStoreConfig("posc"), null);
				Txn txn = store.getTxnManager().createReadTxn()) {
			TripleIndex index = index(store, "posc");
			assertEquals(0L, count(txn, index, true, null, null).entries());
			try (ExactPrefixCursor runs = ChunkedExactIndexCounter.prefixRuns(txn.get(), index, true, null, null, 1,
					() -> false)) {
				assertEquals(null, runs.next());
			}
		}
	}

	private TripleStore seededStore() throws Exception {
		TripleStore store = new TripleStore(dir, new LmdbStoreConfig("posc,spoc"), null);
		SplittableRandom random = new SplittableRandom(42);
		store.startTransaction();
		for (int i = 0; i < 3000; i++) {
			long subject = 1 + random.nextInt(400);
			long predicate = 1 + random.nextInt(PREDICATES);
			// A few objects repeat so that two-field groups span several rows and chunks.
			long object = random.nextInt(4) == 0 ? 1 + random.nextInt(5) : 1 + random.nextLong(1_000_000);
			long context = random.nextBoolean() ? 0 : 1 + random.nextInt(3);
			store.storeTriple(subject, predicate, object, context, random.nextInt(10) != 0);
		}
		store.commit();
		return store;
	}

	private static TripleIndex index(TripleStore store, String fieldSequence) {
		return store.getIndexes()
				.stream()
				.filter(index -> index.toString().equals(fieldSequence))
				.findFirst()
				.orElseThrow();
	}

	private static ExactCount count(Txn txn, TripleIndex index, boolean explicit, byte[] lower, byte[] upper)
			throws Exception {
		return ChunkedExactIndexCounter.count(txn.get(), index, explicit, lower, upper, () -> false);
	}

	/** Every row of the plane as an encoded key of {@code index}, in key order. */
	private static List<byte[]> keys(TripleStore store, Txn txn, TripleIndex index, boolean explicit)
			throws Exception {
		List<byte[]> keys = new ArrayList<>();
		long[] entry = new long[4];
		try (RecordIterator rows = store.getTriples(txn, -1, -1, -1, -1, explicit)) {
			long[] quad;
			while ((quad = rows.next()) != null) {
				index.toEntry(entry, quad[0], quad[1], quad[2], quad[3]);
				keys.add(LmdbExactPrefixRunCursor.encodePrefix(entry));
			}
		}
		keys.sort(Arrays::compareUnsigned);
		return keys;
	}

	private static long bruteForce(List<byte[]> keys, byte[] lower, byte[] upper) {
		return keys.stream().filter(key -> inRange(key, lower, upper)).count();
	}

	private static boolean inRange(byte[] key, byte[] lower, byte[] upper) {
		return (lower == null || Arrays.compareUnsigned(key, lower) >= 0)
				&& (upper == null || Arrays.compareUnsigned(key, upper) < 0);
	}

	private static String prefix(byte[] key, int fields) {
		ByteBuffer buffer = ByteBuffer.wrap(key);
		StringBuilder prefix = new StringBuilder();
		for (int i = 0; i < fields; i++) {
			prefix.append(Varint.readUnsigned(buffer)).append('/');
		}
		return prefix.toString();
	}
}
